import test from 'node:test';import assert from 'node:assert/strict';import {CONTEXTS,create,validate,setContext,swap,evaluate,compare,isEdited} from './engine.js';
test('legacy settings retain values and allocation while adopting the original context',()=>{const old=create();delete old.context;old.actual[2]=53;old.threshold=64;const w=validate(old);assert.equal(w.context,'opportunity');assert.equal(w.actual[2],53);assert.equal(w.threshold,64);assert.deepEqual(w.order,old.order);assert.ok(isEdited(w));assert.throws(()=>validate({...w,context:'missing'}));});
test('low headroom reverses the trigger with inclusive equality and correct asymmetric losses',()=>{const s=create('headroom');s.actual[0]=40;let r=evaluate(s);assert.equal(r.rows[0].forecast,60);assert.equal(r.rows[0].need,true);assert.equal(r.rows[0].act,false);assert.equal(r.rows[0].cost,12);s.actual[0]=25;r=evaluate(s);assert.equal(r.rows[0].forecast,45);assert.equal(r.rows[0].act,true);s.actual[1]=65;r=evaluate(s);assert.equal(r.rows[1].forecast,45);assert.equal(r.rows[1].kind,'falseAlarm');assert.equal(r.rows[1].cost,2);s.actual[2]=45;r=evaluate(s);assert.equal(r.rows[2].need,true);assert.equal(r.rows[2].act,true);});
test('the same swap improves opportunity decisions but worsens review capacity decisions at unchanged accuracy',()=>{const a=create(),b=swap(a,0,5),capacity=setContext(b,'capacity'),base=create('capacity');assert.ok(evaluate(b).loss<evaluate(a).loss);assert.ok(evaluate(capacity).loss>evaluate(base).loss);for(const s of [a,b,base,capacity]){assert.equal(evaluate(s).mae,7.5);assert.equal(evaluate(s).rmse,evaluate(a).rmse);}assert.deepEqual(capacity.order,b.order);assert.equal(a.order[0],0);});
test('pinned allocations share direction, values and loss settings when moving between contexts',()=>{const pin=create();let current=setContext(swap(pin,0,5),'headroom');current.actual[0]=43;current.miss=17;assert.deepEqual(compare(current,pin),evaluate({...current,order:pin.order}));assert.equal(pin.context,'opportunity');assert.equal(pin.actual[0],40);for(const id of Object.keys(CONTEXTS)){const s=create(id);assert.equal(isEdited(s),false);assert.equal(evaluate(s).loss,evaluate(s).misses*s.miss+evaluate(s).falseAlarms*s.falseAlarm);}});
